import React, { useState, useCallback } from 'react';
import { X } from 'lucide-react';
import './UploadFile.css';

const UploadFile = ({ onClose }) => {
  const [files, setFiles] = useState([]);
  const [isDragging, setIsDragging] = useState(false);
  const [uploadProgress, setUploadProgress] = useState({});

  const handleDragEnter = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);

    const droppedFiles = Array.from(e.dataTransfer.files);
    handleFiles(droppedFiles);
  }, []);

  const handleFileSelect = (e) => {
    const selectedFiles = Array.from(e.target.files);
    handleFiles(selectedFiles);
  };

  const handleFiles = (newFiles) => {
    setFiles(prev => [...prev, ...newFiles]);

    // Initialize progress for new files
    const newProgress = {};
    newFiles.forEach(file => {
      newProgress[file.name] = 0;
    });
    setUploadProgress(prev => ({ ...prev, ...newProgress }));

    // Simulate progress for demo purposes
    newFiles.forEach(file => {
      simulateFileProgress(file.name);
    });
  };

  const simulateFileProgress = (fileName) => {
    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 30;
      if (progress > 100) {
        progress = 100;
        clearInterval(interval);
      }
      setUploadProgress(prev => ({
        ...prev,
        [fileName]: Math.round(progress)
      }));
    }, 500);
  };

  const removeFile = (fileName) => {
    setFiles(files.filter(file => file.name !== fileName));
    setUploadProgress(prev => {
      const newProgress = { ...prev };
      delete newProgress[fileName];
      return newProgress;
    });
  };

  return (
    <div className="upload-modal-overlay">
      <div className="upload-modal">
        <button className="close-button" onClick={onClose}>
          <X size={20} />
        </button>

        <div className="upload-header">
          <h2>Please Upload your Model</h2>
          <p>Select model files for upload</p>
        </div>

        <div 
          className={`upload-area ${isDragging ? 'dragging' : ''} ${files.length > 0 ? 'has-files' : ''}`}
          onDragEnter={handleDragEnter}
          onDragOver={(e) => e.preventDefault()}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
        >
          <div className="upload-content">
            <div className="upload-icon">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} 
                      d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
              </svg>
            </div>
            <div className="upload-text">
              <span>Select a file or drag and drop here</span>
              <span className="upload-subtitle">supported: txt, doc, rtf, file size no more than 100 GB</span>
            </div>
            <label className="select-button">
              <span>SELECT FILE</span>
              <input type="file" onChange={handleFileSelect} multiple />
            </label>
          </div>
        </div>

        {files.length > 0 && (
          <div className="file-list">
            <div className="file-list-header">File added</div>
            {files.map((file, index) => (
              <div key={index} className="file-item">
                <div className="file-info">
                  <svg className="file-icon" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" 
                          d="M4 4a2 2 0 012-2h4.586A2 2 0 0112 2.586L15.414 6A2 2 0 0116 7.414V16a2 2 0 01-2 2H6a2 2 0 01-2-2V4z" 
                          clipRule="evenodd" />
                  </svg>
                  <span className="file-name">{file.name}</span>
                </div>
                <div className="file-details">
                  <div className="progress-bar">
                    <div 
                      className="progress-fill"
                      style={{ width: `${uploadProgress[file.name] || 0}%` }}
                    />
                  </div>
                  <span className="file-size">
                    {(file.size / (1024 * 1024)).toFixed(2)} MB
                  </span>
                  <button 
                    className="remove-file"
                    onClick={() => removeFile(file.name)}
                  >
                    <X size={16} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

        <div className="modal-actions">
          <button className="cancel-button" onClick={onClose}>
            Cancel
          </button>
          <button 
            className="upload-button"
            disabled={files.length === 0}
            onClick={() => {
              // Handle upload logic here
              onClose();
            }}
          >
            Upload
          </button>
        </div>
      </div>
    </div>
  );
};

export default UploadFile;
